    public string? ClusterRole { get; set; }

    /// <summary>
    /// Updates the autoscaling configuration for the cluster. Use to enable or disable automatic node scaling. Mode -&gt; (string) [required] Describes whether autoscaling is enabled or disabled for the cluster. Valid values are Enable and Disable . Possible values: o Enable o Disable AutoScalerType -&gt; (string) The type of autoscaler to use. Currently supported value is Kar- penter . Possible values: o Karpenter Shorthand Syntax: Mode=string,AutoScalerType=string JSON Syntax: { "Mode": "Enable"|"Disable", "AutoScalerType": "Karpenter" }
    /// </summary>
    [CliOption("--auto-scaling")]
    public string? AutoScaling { get; set; }

    /// <summary>
    /// The type of orchestrator used for the SageMaker HyperPod cluster. Eks -&gt; (structure) The Amazon EKS cluster used as the orchestrator for the Sage- Maker HyperPod cluster. ClusterArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the Amazon EKS cluster as- sociated with the SageMaker HyperPod cluster. Constraints: o min: 20 o max: 2048 o pattern: arn:aws[a-z\-]*:eks:[a-z0-9\-]*:[0-9]{12}:clus- ter\/[0-9A-Za-z][A-Za-z0-9\-_]{0,99} Slurm -&gt; (structure) The Slurm orchestrator configuration for the SageMaker HyperPod cluster. SlurmConfigStrategy -&gt; (string) The strategy for managing partitions for the Slurm configura- tion. Valid values are Managed , Overwrite , and Merge . Possible values: o Overwrite o Managed o Merge Shorthand Syntax: Eks={ClusterArn=string},Slurm={SlurmConfigStrategy=string} JSON Syntax: { "Eks": { "ClusterArn": "string" }, "Slurm": { "SlurmConfigStrategy": "Overwrite"|"Managed"|"Merge" } }
    /// </summary>
    [CliOption("--orchestrator")]
    public string? Orchestrator { get; set; }

    [CliFlag("--cli-input-json")]
    public bool? CliInputJson { get; set; }

    [CliFlag("--generate-cli-skeleton")]
    public bool? GenerateCliSkeleton { get; set; }

}
